\set ON_ERROR_STOP on
BEGIN;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',label;end if;end$$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when raise_exception or insufficient_privilege or check_violation then return;end;raise exception 'Expected denial: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,aud,role) select ('cf000000-0000-4000-8000-00000000000'||n)::uuid,'billing-'||n||'@example.invalid',now(),'{"pms_admin_provisioned":true}','authenticated','authenticated' from generate_series(1,3)n;
insert into workspaces(id,name) values('cf000000-0000-4000-8000-000000000010','Billing fixture');
insert into workspace_members(workspace_id,user_id,role,display_name) select 'cf000000-0000-4000-8000-000000000010',('cf000000-0000-4000-8000-00000000000'||n)::uuid,case n when 1 then 'owner' when 2 then 'member' else 'client' end,'Person '||n from generate_series(1,3)n;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into projects(id,workspace_id,name,client_name) values('cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000010','Billing project','Billing client'),('cf000000-0000-4000-8000-000000000021','cf000000-0000-4000-8000-000000000010','Other project','Other client');
insert into project_members values('cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','guest');
insert into client_documents(id,workspace_id,project_id,kind,title,status,content,total_cents,created_by) values('cf000000-0000-4000-8000-000000000033','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','Estimate','Budget scope','Approved','{"scope":"Service and external costs","tax_rate":10,"items":[{"description":"Scope","quantity":1,"unit_cents":100000}]}',110000,'cf000000-0000-4000-8000-000000000001');
set local role authenticated;
select pg_temp.ok((preview_scope_budget('cf000000-0000-4000-8000-000000000033')->>'tax_cents')::bigint=10000,'tax preview matches source');
select apply_scope_budget('cf000000-0000-4000-8000-000000000033',0,'create',10000,'Exclude approved third-party allowance');
select pg_temp.ok((select amount=900 and revision=1 from budgets where project_id='cf000000-0000-4000-8000-000000000020'),'service budget excludes tax and allowance');
select pg_temp.denied($q$select apply_scope_budget('cf000000-0000-4000-8000-000000000033',0,'replace',0,'Stale preview')$q$,'stale budget preview');
select pg_temp.denied($q$select apply_scope_budget('cf000000-0000-4000-8000-000000000033',1,'replace',0,'Duplicate source')$q$,'same source not reapplied');
reset role;
insert into client_documents(id,workspace_id,project_id,kind,title,status,content,total_cents,created_by,previous_id,version) values('cf000000-0000-4000-8000-000000000034','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','Estimate','Budget scope revised','Shared','{"scope":"Updated scope","tax_rate":10,"items":[{"description":"Scope","quantity":1,"unit_cents":200000}]}',220000,'cf000000-0000-4000-8000-000000000001','cf000000-0000-4000-8000-000000000033',2);
select pg_temp.denied($q$select preview_scope_budget('cf000000-0000-4000-8000-000000000034')$q$,'unapproved source excluded');
update client_documents set status='Approved' where id='cf000000-0000-4000-8000-000000000034';
select pg_temp.ok((select amount=900 from budgets where project_id='cf000000-0000-4000-8000-000000000020'),'new approval never silently replaces budget');
select pg_temp.denied($q$select preview_scope_budget('cf000000-0000-4000-8000-000000000033')$q$,'old approved version excluded');
select pg_temp.denied($q$select apply_scope_budget('cf000000-0000-4000-8000-000000000034',1,'add',20000,'Cannot add an estimate')$q$,'addition only for change orders');
select apply_scope_budget('cf000000-0000-4000-8000-000000000034',1,'replace',20000,'Replace full service scope with approved revision');
select pg_temp.ok((select amount=1800 and revision=2 from budgets where project_id='cf000000-0000-4000-8000-000000000020'),'explicit replacement preserves revision check');
select pg_temp.ok((select count(*)=2 from budget_scope_history),'both scope allocations retained');
select pg_temp.ok((select source_snapshot->>'title'='Budget scope' and service_cents=90000 and reimbursable_cents=10000 and tax_cents=10000 from budget_scope_history where document_version=1),'original snapshot and allocation retained');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select pg_temp.ok((select count(*)=0 from budget_scope_history),'client cannot read internal budget history');
select pg_temp.denied($q$select preview_scope_budget('cf000000-0000-4000-8000-000000000034')$q$,'client cannot preview internal budget');
reset role;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select delete_workspace('cf000000-0000-4000-8000-000000000010','Billing fixture');
select pg_temp.ok(not exists(select 1 from budget_scope_history where workspace_id='cf000000-0000-4000-8000-000000000010'),'history follows explicit workspace deletion');
ROLLBACK;
